import{_ as a,c as i,a5 as t,o as r}from"./chunks/framework.mFcBg5UA.js";const o="/my-blog/question/network/tcp_and_udp.jpg",c=JSON.parse('{"title":"TCP和UDP的区别","titleTemplate":"前端面试题","description":"","frontmatter":{"outline":"deep","title":"TCP和UDP的区别","titleTemplate":"前端面试题","head":[["link",{"rel":"canonical","href":"https://luffy-d-lufei.github.io/my-blog/question/network/tcp_and_udp.html"}]]},"headers":[],"relativePath":"question/network/tcp_and_udp.md","filePath":"question/network/tcp_and_udp.md","lastUpdated":1724510899000}'),e={name:"question/network/tcp_and_udp.md"};function n(p,l,s,u,h,d){return r(),i("div",null,l[0]||(l[0]=[t('<h1 id="tcp和udp的区别" tabindex="-1">TCP和UDP的区别 <a class="header-anchor" href="#tcp和udp的区别" aria-label="Permalink to &quot;TCP和UDP的区别&quot;">​</a></h1><img src="'+o+'" width="500" height="520"><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="tcp" tabindex="-1">TCP <a class="header-anchor" href="#tcp" aria-label="Permalink to &quot;TCP&quot;">​</a></h3><p>TCP(Transport Control Protocol)即传输控制协议：是一种面向连接的、可靠的、基于字节流的传输层通信协议，由 IETF 的 RFC 793 定义。在简化的计算机网络 OSI 模型中，它完成第四层传输层所指定的功能。</p><h3 id="udp" tabindex="-1">UDP <a class="header-anchor" href="#udp" aria-label="Permalink to &quot;UDP&quot;">​</a></h3><p>UDP(User Datagram Protocol)即用户数据报协议：是一个简单的面向资料包的通信协议，位于 OSI 模型的传输层。该协议由 David P. Reed 在 1980 年设计且在 RFC 768 中被规范。</p><h2 id="连接性和握手" tabindex="-1">连接性和握手 <a class="header-anchor" href="#连接性和握手" aria-label="Permalink to &quot;连接性和握手&quot;">​</a></h2><h3 id="tcp-1" tabindex="-1">TCP <a class="header-anchor" href="#tcp-1" aria-label="Permalink to &quot;TCP&quot;">​</a></h3><p><strong>连接性</strong>:</p><ul><li>TCP 是面向连接的协议，通信前需要建立连接，通信结束后需要断开连接。</li><li>连接建立和断开过程比较复杂，涉及到三次握手和四次挥手。</li></ul><p><strong>握手过程</strong>:</p><ul><li>三次握手： <ol><li>客户端发送一个带有 SYN（同步）标志的数据包，请求建立连接。</li><li>服务器收到后，回复一个带有 SYN 和 ACK（确认）标志的数据包，表示已收到请求并同意建立连接。</li><li>客户端再次回复一个带有 ACK 标志的数据包，确认服务器的回复。连接建立。</li></ol></li><li>四次挥手： <ol><li>客户端发送一个带有 FIN（结束）标志的数据包，表示不再发送数据。</li><li>服务器收到后，回复一个带有 ACK 标志的数据包，确认客户端的 FIN。</li><li>服务器发送一个带有 FIN 标志的数据包，表示不再发送数据。</li><li>客户端收到后，发送一个带有 ACK 标志的数据包，确认服务器的 FIN。连接断开。</li></ol></li></ul><h3 id="udp-1" tabindex="-1">UDP <a class="header-anchor" href="#udp-1" aria-label="Permalink to &quot;UDP&quot;">​</a></h3><p><strong>连接性</strong>:</p><ul><li>UDP 是无连接的协议，通信前不需要建立连接，通信结束后也不需要断开连接。</li></ul><p><strong>握手过程</strong>:</p><ul><li>由于 UDP 是无连接的，因此没有握手过程。发送方可以直接将数据报文发送给接收方，而不需要进行连接建立操作。</li><li>接收方收到数据后，也不会发送确认回复。</li></ul><h2 id="数据传输和可靠性" tabindex="-1">数据传输和可靠性 <a class="header-anchor" href="#数据传输和可靠性" aria-label="Permalink to &quot;数据传输和可靠性&quot;">​</a></h2><h3 id="tcp-2" tabindex="-1">TCP <a class="header-anchor" href="#tcp-2" aria-label="Permalink to &quot;TCP&quot;">​</a></h3><p><strong>数据传输</strong>:</p><ul><li>数据被划分为数据段，每个数据段包含序号和确认号信息，用于保证数据的有序性和可靠性。</li><li>发送方按照序号发送数据段，接收方根据序号进行数据重组，确保数据有序。</li><li>数据被拆分成数据段后，TCP 头部会包含序号、确认号、窗口大小等字段。</li></ul><p><strong>可靠性</strong>:</p><ul><li>TCP 提供可靠的数据传输，通过序号、确认和重传机制保证数据的可靠性。 <ul><li>如果数据段丢失、损坏或乱序，TCP 会自动触发重传机制，确保数据的完整性和顺序性。</li><li>接收方会发送确认来告知发送方数据已经接收。</li></ul></li></ul><h3 id="udp-2" tabindex="-1">UDP <a class="header-anchor" href="#udp-2" aria-label="Permalink to &quot;UDP&quot;">​</a></h3><p><strong>数据传输</strong>:</p><ul><li>数据被划分为数据报文（Datagrams），每个数据报文是一个完整的、独立的数据单元。</li><li>数据报文之间相互独立，没有序号和确认机制，因此不保证数据的有序性。</li></ul><p><strong>可靠性</strong>:</p><ul><li>UDP 不提供可靠性保证，不会自动进行数据重传。</li><li>如果数据报文丢失或损坏，接收方不会自动请求发送方重发数据。</li><li>应用层需要自行处理数据的确认和重传，如果需要。</li></ul><h2 id="​延迟和效率" tabindex="-1">​延迟和效率 <a class="header-anchor" href="#​延迟和效率" aria-label="Permalink to &quot;​延迟和效率&quot;">​</a></h2><h3 id="tcp-3" tabindex="-1">TCP <a class="header-anchor" href="#tcp-3" aria-label="Permalink to &quot;TCP&quot;">​</a></h3><p><strong>延迟</strong>:</p><ul><li>TCP 通常会引入较高的延迟，因为它需要进行握手、确认、重传等机制，以保证数据的可靠性和有序性。</li><li>三次握手和四次挥手过程以及拥塞控制机制等，都可能导致数据传输的延迟增加。</li></ul><p><strong>效率</strong>:</p><ul><li>TCP 在保证可靠性和有序性的同时，会引入一些额外的开销，如序号、确认、窗口大小等字段，以及握手和挥手的数据交换。</li><li>流量控制和拥塞控制机制也会影响数据发送的速率，可能降低效率。</li></ul><h3 id="udp-3" tabindex="-1">UDP <a class="header-anchor" href="#udp-3" aria-label="Permalink to &quot;UDP&quot;">​</a></h3><p><strong>延迟</strong>:</p><ul><li>UDP 通常具有较低的延迟，因为它没有复杂的连接建立和断开过程，也没有确认和重传机制。</li><li>数据可以直接发送，减少了额外的等待时间。</li></ul><p><strong>效率</strong>:</p><ul><li>UDP 具有较高的效率，因为它没有确认、重传、流量控制和拥塞控制机制。</li><li>数据可以更快速地发送，适用于对实时性要求较高的应用。</li></ul><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><h3 id="tcp-4" tabindex="-1">TCP <a class="header-anchor" href="#tcp-4" aria-label="Permalink to &quot;TCP&quot;">​</a></h3><ol><li><p><strong>网页浏览</strong>:TCP 适用于网页浏览，因为它能够保证数据的可靠性和有序性。在浏览网页时，确保页面的各个元素按正确顺序加载很重要。</p></li><li><p><strong>文件传输</strong>:TCP 适用于大文件的传输，如文件下载和上传。它的可靠性保证了文件的完整性，重传机制保证了数据不会丢失。</p></li><li><p><strong>电子邮件</strong>:由于电子邮件的内容往往很重要，需要确保数据的可靠性和有序性。因此，TCP 在电子邮件的传输中得到广泛应用。</p></li><li><p><strong>数据库交互</strong>:数据库交互需要可靠性，确保查询和更新操作按顺序执行。TCP 提供了保证数据完整性的机制。</p></li><li><p><strong>远程登录</strong>: 在远程登录和管理系统时，确保命令的顺序和完整性是关键的。TCP 适用于这种场景。</p></li></ol><h3 id="udp-4" tabindex="-1">UDP <a class="header-anchor" href="#udp-4" aria-label="Permalink to &quot;UDP&quot;">​</a></h3><ol><li><p><strong>实时音视频传输</strong>:UDP 适用于实时音视频传输，如在线视频会议、音频通话和实时直播。在这些应用中，实时性和低延迟更为重要，而丢失少量数据是可以接受的。</p></li><li><p><strong>在线游戏</strong>:在线游戏需要快速的数据传输和实时性，UDP 适合用于传输游戏数据。游戏中的数据包传输速度比可靠性更重要。</p></li><li><p><strong>DNS</strong>:DNS（Domain Name System）解析域名时通常使用UDP。虽然DNS查询也可以使用TCP，但大多数情况下使用UDP以减少延迟。</p></li><li><p><strong>物联网设备</strong>:物联网设备通常需要快速的数据传输和实时性，而且可以容忍一些数据丢失。因此，UDP 适用于与物联网设备通信。</p></li><li><p><strong>SNMP</strong>:简单网络管理协议（SNMP）用于网络设备的管理和监控。UDP 在这种情况下用于传输SNMP消息。</p></li></ol><h2 id="头部开销" tabindex="-1">头部开销 <a class="header-anchor" href="#头部开销" aria-label="Permalink to &quot;头部开销&quot;">​</a></h2><h3 id="tcp-5" tabindex="-1">TCP <a class="header-anchor" href="#tcp-5" aria-label="Permalink to &quot;TCP&quot;">​</a></h3><ul><li><p>TCP 头部包含以下字段：</p><ul><li>源端口号（16位）</li><li>目标端口号（16位）</li><li>序号（32位）</li><li>确认号（32位）</li><li>数据偏移（4位）</li><li>保留位（6位）</li><li>控制标志位（6位）</li><li>窗口大小（16位）</li><li>校验和（16位）</li><li>紧急指针（16位）</li><li>选项（可变长度）</li><li>填充（可变长度）</li></ul></li><li><p>TCP 头部总长度不固定，最少为20字节，最多为60字节（当选项和填充都存在时）。</p></li></ul><p>TCP 头部开销相对较大，因为它包含了多个字段，如序号、确认号、窗口大小等，以保证数据的可靠性和有序性。此外，TCP 还支持选项和填充字段，使头部长度变化。</p><h3 id="udp-5" tabindex="-1">UDP <a class="header-anchor" href="#udp-5" aria-label="Permalink to &quot;UDP&quot;">​</a></h3><ul><li><p>UDP 头部包含以下字段：</p><ul><li>源端口号（16位）</li><li>目标端口号（16位）</li><li>长度（16位）</li><li>校验和（16位）</li></ul></li><li><p>UDP 头部固定长度为8字节。</p></li></ul><p>UDP 头部开销较小，仅包含基本的源端口、目标端口、长度和校验和字段。它没有连接建立、确认和重传机制，因此头部较为简单。</p>',52)]))}const g=a(e,[["render",n]]);export{c as __pageData,g as default};
